from svgkit import *
from dns_figs import WIDE
F1,F5,F2,F3,F4=WIDE
tool_html=r'''<div class="ir-tool" id="ir-tool"><div class="ir-tool-head"><span class="ir-tool-eyebrow">Public resolver check</span><button type="button" class="ir-btn-primary" id="ir-dns-run">Run check</button></div><div id="ir-dns-out" aria-live="polite"><p class="ir-tool-empty">Compares how fast Cloudflare and Google public DNS answer from your browser: your round trip, a new name, and the difference.</p></div><p class="ir-tool-note" id="ir-dns-note">This tests public resolvers only. A browser cannot see which DNS server your device uses, so it cannot time your current one. See "Time your own resolver" below.</p></div>'''
tool_js=r'''<script>(function(){var b=document.getElementById('ir-dns-run'),o=document.getElementById('ir-dns-out'),n=document.getElementById('ir-dns-note');if(!b)return;
var R=[['Cloudflare 1.1.1.1','https://cloudflare-dns.com/dns-query?type=A&name=',{accept:'application/dns-json'}],['Google 8.8.8.8','https://dns.google/resolve?type=A&name=',{}]];
function q(r,name){var s=performance.now();return fetch(r[1]+name,{headers:r[2],cache:'no-store'}).then(function(x){if(!x.ok)throw 0;return x.json()}).then(function(){return performance.now()-s})}
function med(a){a=a.slice().sort(function(x,y){return x-y});return a[Math.floor(a.length/2)]}
async function one(r){await q(r,'example.com');var c=[],u=[],i;for(i=0;i<7;i++)c.push(await q(r,'example.com'));for(i=0;i<5;i++)u.push(await q(r,'x'+Math.random().toString(36).slice(2,10)+'.example.com'));var m=Math.min.apply(null,c),k=med(u);return{name:r[0],c:m,u:k,p:Math.max(0,k-m)}}
async function run(){b.disabled=true;n.textContent='Measuring...';var res=[],i;for(i=0;i<R.length;i++){try{res.push(await one(R[i]))}catch(e){}}
if(!res.length){n.textContent='Tap to refresh.';b.disabled=false;return}
var h='<div class="ir-dns-grid">';
res.forEach(function(r){h+='<div class="ir-dns-card"><div class="ir-dns-name">'+r.name+'</div><div class="ir-dns-stats"><div><span>Round trip</span><strong>'+Math.round(r.c)+' ms</strong></div><div><span>New name</span><strong>'+Math.round(r.u)+' ms</strong></div><div><span>Penalty</span><strong>'+Math.round(r.p)+' ms</strong></div></div></div>'});
var rt=Math.min.apply(null,res.map(function(r){return r.c})),worst=Math.max.apply(null,res.map(function(r){return r.p})),t='These are public resolvers measured from your browser, not the one your device uses now. ';
t+=worst<100?'Both answer new names quickly from here. ':'At least one adds a noticeable delay on new names from here. ';
if(rt>150)t+='Your round trip to them is about '+Math.round(rt)+' ms, so a closer resolver, often one run by your ISP, may beat them. ';
t+='To decide, time your current resolver with dig or PowerShell (see below) and compare. Differences under about 30 ms are normal measurement noise.';
o.innerHTML=h+'</div><p class="ir-tool-note">'+t+'</p>';
n.textContent='Penalty = new-name time minus your fastest round trip. Under 100 ms is normal, 100 to 300 ms is noticeable, over 300 ms is slow (the rule of thumb on this page).';b.textContent='Run again';b.disabled=false}
b.addEventListener('click',run)})();</script>'''
S=dict(slug='how-to-fix-slow-dns-lookup',date='2026-11-01',date_label='1 November 2026',plan='D1',tool_html=tool_html,tool_js=tool_js,
title='How to Fix Slow DNS Lookup (Test It, Then Fix It)',headline='How to Fix Slow DNS Lookup: Time Your Resolver, Compare Public Ones, Then Change DNS or Flush the Cache',
desc='Slow DNS lookup delays every page. Time your resolver, compare public ones live, then change DNS, flush the cache and check your VPN and router.',
kw=['how to fix slow dns lookup','slow dns lookup','dns lookup slow','how to check dns speed','change dns server','flush dns cache'],about='DNS lookup performance',section='Networking Troubleshooting',crumb='Fix Slow DNS Lookup',
h1='How to Fix <span class="ndic-highlight">Slow DNS Lookup</span>',tagline='Time your own resolver, compare public ones from your browser, and switch only if one is clearly faster.',kicker='DNS &amp; Performance',cta='Compare Resolvers',
qa_title='Time your resolver first, then switch only if a public one is clearly faster',
qa_body="A slow DNS lookup is a delay in turning a website name into an IP address, and it delays the whole page. Time your current resolver with dig or PowerShell, then use the check on this page to compare public resolvers from your location. Switch only if one is clearly faster, then flush the DNS cache and check your VPN and router.",
og_title='How to Fix <span style="color:#38bdf8">Slow DNS Lookup</span>',og_sub='Time it, compare resolvers, then fix it',og_chip='DNS <span style="color:#38bdf8">42 ms</span>',
card_desc='Time your DNS resolver, compare public resolvers in your browser, then fix slow lookups by changing DNS, flushing the cache and checking your router and VPN.',
panel=dict(eyebrow='Live Network panel',h3='Check the connection underneath',p='DNS is only one part of speed. The <a href="/intelligence/live-network">Live Network panel</a> shows latency, jitter and packet loss, which tell you whether the problem is DNS or the connection itself.',href='/intelligence/live-network',btn='Open Live Network'),
sections=[
('test','Compare Public DNS Resolvers From Where You Are',''),
('what','What a DNS Lookup Is and Why It Gets Slow',r'''<p>Every website you open has a name, and computers route by number. A DNS lookup is the step that turns the name into an <a href="/learn/what-is-an-ip-address">IP address</a>. Your device asks a resolver, usually run by your ISP or a public provider. If the resolver already knows the answer it replies at once. If it does not, it walks from the root servers to the top-level domain and then to the server that owns the name, as defined in RFC 1034 and RFC 1035.</p>'''+fig(F1,'The resolver does the legwork: it asks each level in turn, hands you one answer and remembers it.')+r'''<p>Resolvers keep answers for a time set by each record, called the TTL. That is why a site you visit often loads its name quickly, and a name you have never asked for takes longer. Your browser, your operating system and often your router keep their own caches on top of that.</p><p>Lookup time matters because it comes first. Nothing else about a page can start until the name has an address, so a slow lookup delays every new site you open.</p>'''+fig(F5,'Same page, same connection: only the DNS step differs. Everything after it waits.')),
('slow','What Counts as Slow',r'''<p>A lookup includes the trip to the resolver, so raw numbers depend on where you are. The fix is to compare two lookups of the same kind. The tool above reports a penalty: the time for a new name minus your fastest round trip to the resolver. You can do the same for your own resolver with the commands further down: the first lookup of a site you rarely visit, minus the second, is the resolver's own work.</p>'''+table('Rule of thumb for the penalty',['Penalty','What it usually means','Next step'],[['Under 100 ms','Normal. The resolver is doing its job','Nothing to fix here'],['100 to 300 ms','Noticeable on new sites','Compare with another resolver'],['Over 300 ms','Slow. Often a distant, overloaded or partly failing resolver','Change resolver, then retest']])+r'''<p>These ranges are this page's own rule of thumb, not an industry standard. Also look at the round trip. If it is already 150 ms or more, as it often is on mobile networks, distance dominates every lookup, and a resolver run by your ISP can be closer and faster than a public one.</p>'''),
('causes','Common Causes of Slow Lookups',r'''<p>Most slow lookups trace back to a short list of causes. A distant or overloaded resolver is a frequent one. An unresponsive DNS server in your list is the classic hidden one: the device waits for it to time out before trying the next, so some lookups take seconds. An unreachable IPv6 DNS server causes the same wait before the device falls back to IPv4. Routers that forward DNS can add delay or get stuck, VPN and security software can redirect lookups to their own servers, and a browser's own Secure DNS setting can bypass the DNS your device is set to use.</p>'''+fig(F2,'Where each cause sits on the path from your device to the resolver.')+r'''<p>If pages also stall after the name resolves, the cause is probably not DNS. Our guide to <a href="/learn/why-does-my-internet-speed-fluctuate">why internet speed fluctuates</a> covers congestion and Wi-Fi problems that look similar.</p>'''),
('measure','Time Your Own Resolver',r'''<p>The browser check cannot see your current resolver, so time it from the command line. Use a site you rarely visit, because a popular name is probably already cached.</p><ol class="ir-steps"><li><strong>Mac and Linux:</strong> run <code class="ir-code">dig sitename.com</code> and read the Query time line. Run it again: the second answer comes from the resolver's cache, and the difference is its work. To compare, run <code class="ir-code">dig sitename.com @1.1.1.1</code> or <code class="ir-code">dig sitename.com @8.8.8.8</code> the same way.</li><li><strong>Windows:</strong> run <code class="ir-code">ipconfig /flushdns</code>, then <code class="ir-code">Measure-Command { Resolve-DnsName sitename.com }</code> in PowerShell. Only the first run reflects your resolver. The repeat is answered by the local Windows cache.</li></ol>'''+fig(F4,'Time your own resolver first, then compare it with public ones.')),
('fix','Fix 1: Change the DNS Resolver',r'''<p>Switching helps when your current resolver is the slow part. It does not help if the new one is far from you, so compare before and after. Three widely used public resolvers are listed below. Set one on a single device, or on the router so every device that uses it benefits.</p>'''+fig(F3,'Set on one device and only that device changes. Set on the router and every device that uses it changes.')+table('Public resolvers compared',['Resolver','Addresses','Notes'],[['Cloudflare','1.1.1.1, 1.0.0.1. Android name: one.one.one.one','General purpose, supports DNS over HTTPS'],['Google Public DNS','8.8.8.8, 8.8.4.4. Android name: dns.google','General purpose, supports DNS over HTTPS'],['Quad9','9.9.9.9. Android name: dns.quad9.net','Blocks known malicious domains'],['Your ISP','Assigned automatically','Varies by provider']])+table('Where to change DNS',['Device','Where','What to enter'],[['Windows 11','Settings, Network &amp; internet, your Wi-Fi or Ethernet connection, DNS server assignment, Edit','Choose Manual, turn on IPv4, enter preferred and alternate addresses'],['Mac','System Settings, Network, your connection, Details, DNS','Add addresses with the plus button'],['iPhone and iPad','Settings, Wi-Fi, the info icon next to your network, Configure DNS','Choose Manual and add servers'],['Android','Look for Private DNS in the network or connection settings (names vary by maker)','Choose the private DNS provider and enter the name from the table above'],['Router','Router admin page, Internet or WAN settings','Enter primary and secondary DNS. See the <a href="/learn/find-router-ip-address">router IP guide</a> to sign in']])+r'''<p>After changing it, flush the cache (next section) and repeat your measurement. To undo, set the connection back to automatic.</p>'''),
('flush','Fix 2: Flush the DNS Cache',r'''<p>A cache can hold a bad or outdated answer. Flushing clears it. This is quick and safe, and your device simply asks again.</p>'''+table('Flush commands',['System','Command'],[['Windows','<code class="ir-code">ipconfig /flushdns</code>'],['macOS','<code class="ir-code">sudo dscacheutil -flushcache; sudo killall -HUP mDNSResponder</code>'],['Linux (systemd-resolved)','<code class="ir-code">resolvectl flush-caches</code>']])+r'''<p>Browsers keep a separate cache. Restarting the browser clears it.</p>'''),
('vpn','Fix 3: Check Your VPN, Router and Security Software',r'''<p>A VPN usually sends lookups to its own servers, so a slow VPN resolver means slow lookups even when your own is fast. Turn the VPN off and test again. The <a href="/intelligence/vpn-proxy">VPN and Proxy panel</a> shows whether your connection is routed through one. Then restart the router, since its DNS forwarder can get stuck, and check whether security or parental-control software filters DNS.</p>''')],
logic="Explain what a lookup is, define slow in a way that removes distance, list the causes, then separate measuring your own resolver from comparing public ones. Change DNS only when a comparison supports it, and measure again afterwards.",
method="The browser check sends DNS-over-HTTPS queries to Cloudflare and Google. It times one warm-up, seven repeat lookups of example.com (the fastest is your round trip) and five lookups of random new names (the median is the new-name time). It cannot see your current DNS server, so the commands in the page time that one. Penalty ranges are a rule of thumb, and results depend on your location and connection.",
cites=[('RFC 1034: Domain Names, Concepts and Facilities','https://www.rfc-editor.org/rfc/rfc1034'),('RFC 1035: Domain Names, Implementation and Specification','https://www.rfc-editor.org/rfc/rfc1035'),('RFC 8484: DNS Queries over HTTPS (DoH)','https://www.rfc-editor.org/rfc/rfc8484'),('Cloudflare: DNS over HTTPS JSON format','https://developers.cloudflare.com/1.1.1.1/encryption/dns-over-https/make-api-requests/dns-json/'),('Google Public DNS: JSON API','https://developers.google.com/speed/public-dns/docs/doh/json'),('Microsoft Learn: Resolve-DnsName','https://learn.microsoft.com/en-us/powershell/module/dnsclient/resolve-dnsname')],
faq_sub='Twelve questions on DNS lookup time, resolvers and fixes.',
faq=[('What is a DNS lookup?','It is the step that turns a website name into an IP address so your device knows where to connect.'),
('What is a good DNS lookup time?','It depends on your distance from the resolver, so compare a first lookup with a repeat of the same name. A difference under about 100 ms is normal on this page\'s rule of thumb.'),
('Will changing my DNS make my internet faster?','It speeds up the lookup step, so new sites open sooner. It does not raise your download speed.'),
('My round trip is about 200 ms. Is that bad?','It is common on mobile networks and for users far from the resolver. It means distance, not DNS work, dominates. A resolver closer to you, often your ISP\'s own, may be faster, so compare at the device before switching.'),
('Which DNS server is the fastest?','It varies by location and network. Run the public resolver check, time your own resolver with dig or PowerShell, then compare. Cloudflare, Google and Quad9 are common choices.'),
('Is it safe to use a public DNS resolver?','Yes for most people, but the resolver sees the names you look up, so read its privacy policy. Quad9 also blocks known malicious domains.'),
('Why is only the first visit to a site slow?','The first lookup is uncached. After that, the answer is stored for the record\'s TTL, so repeat visits are faster.'),
('Does clearing the DNS cache help?','Only if a stale or bad answer is stored. It will not fix a slow resolver, but it is quick and harmless.'),
('Can a VPN slow down DNS?','Yes. A VPN usually sends lookups to its own servers, so a slow one slows everything. Test with the VPN off.'),
('Can the browser check see my current DNS server?','No. Browsers do not expose it, so the check tests public resolvers and you time your own with dig or PowerShell.'),
('My DNS change seems to have no effect. Why?','The browser may use its own Secure DNS provider, which ignores the DNS set on your device. Check the privacy or security settings of Chrome, Edge or Firefox.'),
('Should I use DNS over HTTPS?','It encrypts lookups between you and the resolver, which helps privacy on shared networks. It does not by itself make lookups faster.')])
